import{_ as s,a0 as i,w as l,s as g,I as t,x as e,a1 as n,A as a,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"惠普买了 WebOS 的面包，谷歌雇了 WebOS 的烘焙师——安卓设计革命的起点 | LCTT x X-CMD","titleTemplate":false,"description":"2011 年安卓 3.0 蜂巢发布，Matias Duarte 从 Palm 跳到谷歌后第一次掌舵安卓设计。Xoom 平板、急切发布的科幻主题、闭源决策——安卓设计革命的起点。15 年后看，蜂巢看似失败，但它埋下的\\"软件导航键 + 多任务卡片 + 系统级 UI 主管\\"三件套，今天统治所有移动 OS。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"惠普买了 WebOS 的面包，谷歌雇了 WebOS 的烘焙师——安卓设计革命的起点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2011 年安卓 3.0 蜂巢发布，Matias Duarte 从 Palm 跳到谷歌后第一次掌舵安卓设计。Xoom 平板、急切发布的科幻主题、闭源决策——安卓设计革命的起点。15 年后看，蜂巢看似失败，但它埋下的\\"软件导航键 + 多任务卡片 + 系统级 UI 主管\\"三件套，今天统治所有移动 OS。"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/16 - The history of Android.digest","title":"惠普买了 WebOS 的面包，谷歌雇了 WebOS 的烘焙师——安卓设计革命的起点","tag":"The history of Android","desc":"2011 年安卓 3.0 蜂巢发布，Matias Duarte 从 Palm 跳到谷歌后第一次掌舵安卓设计。Xoom 平板、急切发布的科幻主题、闭源决策——安卓设计革命的起点。15 年后看，蜂巢看似失败，但它埋下的\\"软件导航键 + 多任务卡片 + 系统级 UI 主管\\"三件套，今天统治所有移动 OS。"},"relativePath":"The history of Android/16 - The history of Android.digest.md","filePath":"[post].md"}'),d={name:"The history of Android/16 - The history of Android.digest.md"};function p(h,o,m,S,q,O){const r=i("Link");return l(),g("div",null,[o[13]||(o[13]=t("h1",{id:"惠普买了-webos-的面包-谷歌雇了-webos-的烘焙师——安卓设计革命的起点",tabindex:"-1"},[e("惠普买了 WebOS 的面包，谷歌雇了 WebOS 的烘焙师——安卓设计革命的起点 "),t("a",{class:"header-anchor",href:"#惠普买了-webos-的面包-谷歌雇了-webos-的烘焙师——安卓设计革命的起点","aria-label":"Permalink to “惠普买了 WebOS 的面包，谷歌雇了 WebOS 的烘焙师——安卓设计革命的起点”"},"​")],-1)),t("blockquote",null,[t("p",null,[o[1]||(o[1]=e("老文新评 #009 · ",-1)),n(r,{href:"https://lctt.x-cmd.com/The%20history%20of%20Android/16%20-%20The%20history%20of%20Android/",rel:"nofollow noopener"},{default:a(()=>[...o[0]||(o[0]=[e("lctt.x-cmd.com",-1)])]),_:1}),o[2]||(o[2]=e(" · 2014-01-01",-1))])]),o[14]||(o[14]=u('<p>2010 年 4 月，惠普花 10 亿美元收购 Palm，买下了 WebOS 这个&quot;拥有优秀 UI 的移动操作系统&quot;。但 WebOS 的首席设计师 Matias Duarte 没跟着去惠普——2010 年 5 月他跳到了谷歌。一年后安卓 3.0 蜂巢发布，被普遍认为是安卓&quot;设计复兴&quot;的起点。Ron Amadeo 在编年史第十五篇里讲了一个冷笑话：<strong>惠普买下了面包，谷歌雇走了烘焙师</strong>。</p><p>15 年后再看，蜂巢看似失败，但它埋下的三件套今天统治所有移动 OS——Xoom 在 iPad 2 面前溃败，半年后 Google 匆忙把代码合并回主线，但「软件导航键 + 多任务卡片 + 系统级 UI 主管」这三件套，今天 iOS / iPadOS / Vision Pro / 鸿蒙都在用。</p><h2 id="文章讲了啥" tabindex="-1">文章讲了啥 <a class="header-anchor" href="#文章讲了啥" aria-label="Permalink to “文章讲了啥”">​</a></h2><p>Ron 把这章的重点放在三个变革上：</p><ul><li><strong>设计师主政的开始</strong>：Matias Duarte 被任命为安卓用户体验主管，第一次有人公开掌管安卓外观。整个界面被重构：黑色背景、蓝色光晕、六边形蜂巢壁纸——科幻感十足</li><li><strong>软件按键取代实体键</strong>：蜂巢引入系统栏，把返回/菜单/Home 全部软件化。这意味着任何带触摸屏的设备都能跑安卓，不再依赖实体键</li><li><strong>&quot;最近应用&quot;列表的诞生</strong>：受 WebOS 卡片式多任务启发，安卓终于有了可视化的任务切换——尽管初代版本不能滚动</li></ul><p>但 Ron 也批评了蜂巢的急功近利：发布时不稳、SD 卡不工作、Flash 不支持、源码不开源。这一切都是因为谷歌不想让手机社区拿&quot;半生不熟的蜂巢&quot;做移植。</p><h2 id="_15-年后重读" tabindex="-1">15 年后重读 <a class="header-anchor" href="#_15-年后重读" aria-label="Permalink to “15 年后重读”">​</a></h2><h3 id="这些观点今天还成立吗" tabindex="-1">这些观点今天还成立吗？ <a class="header-anchor" href="#这些观点今天还成立吗" aria-label="Permalink to “这些观点今天还成立吗？”">​</a></h3><ul><li>✅ <strong>软件按键能取代实体键</strong> —— 早已普及，全面屏更进一步</li><li>✅ <strong>Matias Duarte 主管安卓设计</strong> —— 之后他主导 Material Design</li><li>✅ <strong>WebOS 卡片式多任务是好的设计</strong> —— 现代安卓/iOS 都借鉴了</li><li>✅ <strong>蜂巢科幻主题需要淡化</strong> —— 后续版本确实在淡化</li><li>⚠️ <strong>不开源平板源码是正确选择</strong> —— 后来谷歌放弃了这个策略</li><li>❌ <strong>平板需要独立于手机的系统</strong> —— 后来的 ChromeOS/iPadOS 反而做了融合</li></ul><h3 id="三件安卓设计遗产-今天统治所有移动-os" tabindex="-1">三件安卓设计遗产，今天统治所有移动 OS <a class="header-anchor" href="#三件安卓设计遗产-今天统治所有移动-os" aria-label="Permalink to “三件安卓设计遗产，今天统治所有移动 OS”">​</a></h3><p>15 年后回看，蜂巢看似失败，但它埋下的三件套今天统治所有移动 OS：</p><p><strong>第一件：软件导航键</strong>。蜂巢被批评的&quot;屏幕底部黑条&quot;后来被证明是远见——所有全面屏手机的实现都依赖这套逻辑。Apple 从 iPhone X（2017）开始也切到软件导航键，本质是同一逻辑。</p><p><strong>第二件：卡片式多任务</strong>。WebOS 的卡片式任务管理被 Duarte 复制到安卓 3.0，今天 iOS / iPadOS / Vision Pro 的多任务设计都带着这套基因——Android 至今的&quot;最近应用&quot;和 iOS 的 App Switcher 同源。</p><p><strong>第三件：系统级 UI 主管</strong>。Duarte 是安卓史上第一个&quot;公开管设计&quot;的人。在他之前没人觉得安卓需要&quot;设计 VP&quot;——微软、苹果也都没有这个岗位。蜂巢之后，<strong>Google 设了 Material Design 部门、苹果设了 Human Interface 部门、华为设了 EMUI 设计部</strong>——这个组织架构本身就是 Duarte 影响的延续。</p><h3 id="蜂巢闭源-14-个月-安卓社区炸锅——但实际推动了安卓模块化" tabindex="-1">蜂巢闭源 14 个月，安卓社区炸锅——但实际推动了安卓模块化 <a class="header-anchor" href="#蜂巢闭源-14-个月-安卓社区炸锅——但实际推动了安卓模块化" aria-label="Permalink to “蜂巢闭源 14 个月，安卓社区炸锅——但实际推动了安卓模块化”">​</a></h3><p>2011 年蜂巢源码不开源这件事，<strong>Ron 当年把它讲成 Google 的&quot;傲慢决策&quot;</strong>——安卓一直开源，凭什么这次不开。</p><p>15 年后回看，<strong>闭源决策反而意外推动了 Project Treble 和 GKI 的诞生</strong>。</p><p>Google 当年闭源的理由是&quot;不想让手机社区拿半生不熟的蜂巢做移植&quot;——这个逻辑的本质是&quot;模块化尚未成熟，源码开放会失控&quot;。结果就是 Google 在闭源期间被迫做出更干净的模块边界——HAL 层、Vendor 接口、System 层开始解耦。</p><p><strong>开放源码的代价是混乱，闭源的代价是被骂，但回报是模块化</strong>。Google 选了&quot;先模块化、再开源&quot;的路，2013 年蜂巢源码重新开放时，已经具备主干的兼容性。2017 年 Project Treble 上线时（Android 8.0），这种&quot;模块化先行&quot;思路成为产品策略。</p><p><strong>这是 Android 当年给整个开源世界留下的方法论</strong>：当一个项目还没设计好边界时，先别开源，先把模块切干净，再放开。</p><h3 id="平板需要独立-os-这件事-15-年后被证明错了" tabindex="-1">&quot;平板需要独立 OS&quot;这件事 15 年后被证明错了 <a class="header-anchor" href="#平板需要独立-os-这件事-15-年后被证明错了" aria-label="Permalink to “平板需要独立 OS这件事 15 年后被证明错了”">​</a></h3><p>Ron 当年特别强调蜂巢的&quot;只为平板设计&quot;——把平板当作独立的硬件形态。这套思路跟 Surface / iPad 当年的策略一致。</p><p>15 年后回看，<strong>&quot;平板需要独立 OS&quot;是被打脸的设计哲学</strong>。Google 在 2012-2014 年走了 2 年弯路（Android 4.0 重新把平板和手机合并为通用版本），2023 年重启平板路线（Pixel Tablet）时直接用手机 Android 14——<strong>根本没专属 OS</strong>。</p><p>iPadOS 是 2019 年才从 iOS 分离的，本质是同一套内核加平板 UI。鸿蒙在 HarmonyOS NEXT 时代更是把手机、平板、电视、车机、PC 用一套内核覆盖——彻底放弃&quot;分形态设计&quot;。</p><p><strong>这件事的教训是 2026 年所有 OS 设计哲学都该记住的</strong>：<strong>模块化优于专门化</strong>。15 年前 Google 想给平板做专门 OS，今天所有人都用同一套系统跨设备运行。</p><p><strong>AI Agent 元年这也成立</strong>——你想给&quot;AI 平板&quot;、&quot;AI PC&quot;、&quot;AI 手机&quot;做不同的 OS 吗？还是做一套 Agent OS 跨设备跑？<strong>所有大公司选了后者</strong>——OpenAI ChatGPT、Anthropic Claude、Google Gemini、Apple Intelligence 都是 device-agnostic 的。</p><h3 id="matias-duarte-是被严重低估的安卓关键人物" tabindex="-1">Matias Duarte 是被严重低估的安卓关键人物 <a class="header-anchor" href="#matias-duarte-是被严重低估的安卓关键人物" aria-label="Permalink to “Matias Duarte 是被严重低估的安卓关键人物”">​</a></h3><p>蜂巢这一篇最有价值的不是技术，是<strong>Ron Amadeo 让读者认识 Matias Duarte 这个人</strong>。</p><p>Duarte 在 Palm 设计 WebOS 时已经做出&quot;卡片式多任务&quot;、&quot;手势驱动&quot;这些影响一代的设计。他 2010 年跳到 Google 时带的不是单个项目，是<strong>一整套设计哲学</strong>。15 年后 Google 的 Material Design、Pixel UI、ChromeOS 系统级 UI、Gemini 交互范式，都跟 Duarte 当年那一跳有直接关系。</p><p><strong>Duarte 是 Pixels Pixel、Material Design 的真正缔造者</strong>——但他的名字在科技媒体上远不如 Steve Jobs / Jony Ive 知名。<strong>这是开源/消费 OS 设计师的真实处境</strong>：你做出革命性 UI，但没人记住你。</p><p>AI Agent 元年的今天，这种&quot;无名设计师&quot;的传统仍在延续——Anthropic 的 Amanda Askell、OpenAI 的 Christine Payne、Google 的 Noam Shazeer，他们设计的产品每天影响 10 亿人，但没人知道他们的名字。</p><h3 id="最尴尬也最重要的版本" tabindex="-1">最尴尬也最重要的版本 <a class="header-anchor" href="#最尴尬也最重要的版本" aria-label="Permalink to “最尴尬也最重要的版本”">​</a></h3><p>蜂巢是安卓史上最尴尬但最重要的版本之一。<strong>它的失败让 Google 学会了两个事</strong>：</p><p>第一，<strong>模块化优先于开放</strong>——源码可以不开，但模块边界必须切干净 第二，<strong>跨形态优于专属形态</strong>——平板不需要专属 OS，平板需要&quot;通用 OS 的平板模式&quot;</p><p><strong>这两件事 15 年后成为所有 OS 设计的基础共识</strong>。Linux 内核、鸿蒙 NEXT、ChromeOS、Fuchsia 都在用这套思路。</p><p>AI Agent 元年的今天，&quot;蜂巢式失败&quot;仍然在上演——<strong>Vision Pro 2、Rabbit R1、Humane AI Pin，都是&quot;先做专属硬件 + 专属 OS + 专属 AI&quot;</strong>。2026 年看，它们都活不过 3 年。蜂巢当年留下的教训是：先把通用 OS 做对，再考虑专属硬件。</p><hr><p><strong>出处</strong></p>',38)),t("ul",null,[t("li",null,[o[4]||(o[4]=t("strong",null,"原文",-1)),o[5]||(o[5]=e("（ARR 风险）：",-1)),n(r,{href:"http://arstechnica.com/gadgets/2011/03/ars-reviews-the-motorola-xoom/",rel:"nofollow noopener"},{default:a(()=>[...o[3]||(o[3]=[e("arstechnica.com",-1)])]),_:1})]),t("li",null,[o[7]||(o[7]=t("strong",null,"LCTT 译稿源档",-1)),o[8]||(o[8]=e("：",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject/blob/master/sources/tech/20140101%20%E5%AE%89%E5%8D%93%E7%BC%96%E5%B9%B4%E5%8F%B2%EF%BC%8816%EF%BC%89.md"},{default:a(()=>[...o[6]||(o[6]=[e("github.com/LCTT/TranslateProject",-1)])]),_:1})]),t("li",null,[o[10]||(o[10]=t("strong",null,"原译",-1)),o[11]||(o[11]=e("：",-1)),n(r,{href:"https://lctt.x-cmd.com/The%20history%20of%20Android/16%20-%20The%20history%20of%20Android/"},{default:a(()=>[...o[9]||(o[9]=[e("lctt.x-cmd.com",-1)])]),_:1})]),o[12]||(o[12]=t("li",null,[t("strong",null,"发布"),e("：2014-01-01")],-1))]),o[15]||(o[15]=t("hr",null,null,-1))])}const P=s(d,[["render",p]]);export{f as __pageData,P as default};
